INSERT INTO "Role" ("id", "storeId", "name", "description", "isSystem", "scopeLevel", "createdAt", "updatedAt") SELECT 'staff_' || md5(s.id || 'ผู้จัดการหอพัก'), s.id, 'ผู้จัดการหอพัก', 'ดูแลห้อง ผู้เช่า บิล สลิป และสมาชิกทีมภายในสาขาที่ได้รับสิทธิ์', false, 'BRANCH', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM "Store" s WHERE s."deletedAt" IS NULL ON CONFLICT ("storeId", "name") DO NOTHING;
INSERT INTO "RolePermission" ("roleId", "permissionId") SELECT r.id, p.id FROM "Role" r JOIN "Store" s ON s.id=r."storeId" CROSS JOIN "Permission" p WHERE r.id='staff_' || md5(s.id || 'ผู้จัดการหอพัก') AND p.key IN ('branch.view','property.view','property.create','property.update','room.view','room.create','room.update','room.transfer','resident.view','resident.create','resident.update','contract.view','contract.create','contract.update','contract.invite','meter.view','meter.create','meter.update','invoice.view','invoice.create','invoice.update','invoice.issue','payment.view','payment.approve','notification.send','settings.view','settings.update','report.view','report.export','user.view','user.create','user.update') ON CONFLICT DO NOTHING;
INSERT INTO "Role" ("id", "storeId", "name", "description", "isSystem", "scopeLevel", "createdAt", "updatedAt") SELECT 'staff_' || md5(s.id || 'การเงิน'), s.id, 'การเงิน', 'ออกบิล ตรวจสลิป และส่งออกรายงานการเงินในสาขาที่ได้รับสิทธิ์', false, 'BRANCH', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM "Store" s WHERE s."deletedAt" IS NULL ON CONFLICT ("storeId", "name") DO NOTHING;
INSERT INTO "RolePermission" ("roleId", "permissionId") SELECT r.id, p.id FROM "Role" r JOIN "Store" s ON s.id=r."storeId" CROSS JOIN "Permission" p WHERE r.id='staff_' || md5(s.id || 'การเงิน') AND p.key IN ('branch.view','property.view','room.view','resident.view','contract.view','meter.view','invoice.view','invoice.create','invoice.update','invoice.issue','payment.view','payment.approve','notification.send','settings.view','report.view','report.export') ON CONFLICT DO NOTHING;
INSERT INTO "Role" ("id", "storeId", "name", "description", "isSystem", "scopeLevel", "createdAt", "updatedAt") SELECT 'staff_' || md5(s.id || 'ดูรายงาน'), s.id, 'ดูรายงาน', 'ดูข้อมูลห้อง ผู้เช่า บิล และรายงาน โดยแก้ไขหรืออนุมัติไม่ได้', false, 'BRANCH', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM "Store" s WHERE s."deletedAt" IS NULL ON CONFLICT ("storeId", "name") DO NOTHING;
INSERT INTO "RolePermission" ("roleId", "permissionId") SELECT r.id, p.id FROM "Role" r JOIN "Store" s ON s.id=r."storeId" CROSS JOIN "Permission" p WHERE r.id='staff_' || md5(s.id || 'ดูรายงาน') AND p.key IN ('branch.view','property.view','room.view','resident.view','invoice.view','payment.view','report.view','report.export') ON CONFLICT DO NOTHING;
